using UnityEngine;
namespace World.Dungeon01
{
	/// <summary>
	///     <para>
	///         Generates a rectangular room from given floor and wall tiles, with entrance and exit on opposing shorter walls, and
	///         minimum width of 3 tiles. Corners and walls are using pillars. Entrance an exit are generated by connectors.
	///     </para>
	///     <para>
	///         Example of 3x4 layout:
	///     </para>
	///     <code>
	///   #- -#
	///   |   |
	///   |   |
	///   #- -#
	///  </code>
	/// </summary>
	public class StraightRoom : DungeonTileset
	{
		public void Generate(Vector3 startPosition, Vector3 direction, int roomWidth, int roomHeight)
		{
			Debug.Log($"Generating straight room: position={startPosition}, direction={direction}");

			var position = startPosition;
			for (var z = 1; z <= roomHeight; z++)
			{
				for (var x = 1; x <= roomWidth; x++)
				{
					if (x == 1 && z == 1)
					{
						Instantiate(PrefabFromCache(RoomCornerLL), position, Quaternion.identity);
					}
					else if (x == roomWidth && z == 1)
					{
						Instantiate(PrefabFromCache(RoomCornerLR), position, Quaternion.identity);
					}
					else if (x == 1 && z == roomHeight)
					{
						Instantiate(PrefabFromCache(RoomCornerUL), position, Quaternion.identity);
					}
					else if (x == roomWidth && z == roomHeight)
					{
						Instantiate(PrefabFromCache(RoomCornerUR), position, Quaternion.identity);
					}
					else if (x == 1 && z > 1)
					{
						Instantiate(PrefabFromCache(RoomWallVL), position, Quaternion.identity);
						Instantiate(PrefabFromCache(TorchWall), position + new Vector3(0.1f, 2f, -2f), Quaternion.Euler(0f, 90f, 0f));
					}
					else if (x == roomWidth && z > 1)
					{
						Instantiate(PrefabFromCache(RoomWallVR), position, Quaternion.identity);
						Instantiate(PrefabFromCache(TorchWall), position + new Vector3(3.9f, 2f, -2f), Quaternion.Euler(0f, -90f, 0f));
					}
					else if (1 < x && x < roomWidth && z == roomHeight)
					{
						Instantiate(PrefabFromCache(RoomWallHU), position, Quaternion.identity);
					}
					else
					{
						Instantiate(PrefabFromCache(FloorFlat4m), position, Quaternion.identity);
					}

					position.x += TileSize;
				}

				position.z += TileSize;
				position.x = startPosition.x;
			}
		}
	}
}
